const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  // Define the Madre de Dios region in Peru using FAO GAUL administrative boundaries.
  const gaul = ee.FeatureCollection('FAO/GAUL/2015/level2');
  const geom = gaul.filter(ee.Filter.and(
    ee.Filter.eq('ADM0_NAME', 'Peru'),
    ee.Filter.eq('ADM1_NAME', 'Madre de Dios')
  )).geometry();

  if (geom.area().getInfo() === 0) {
    console.log("Could not find Madre de Dios geometry.");
    console.log("C1");
    return;
  }

  const hansen = ee.Image('UMD/hansen/global_forest_change_2023_v1_11');
  const treeCoverThreshold = 10; // Percent tree cover to be considered forest

  // 2. Data Acquisition & Processing
  // Mask function to get forest cover for a specific year.
  // Forest is defined as treecover2000 > treeCoverThreshold AND
  // (no loss OR loss happened after the specified year).
  const getForestCover = (year) => {
    const lossYearBand = hansen.select('lossyear');
    const treeCover2000 = hansen.select('treecover2000');

    // pixels where lossyear is 0 (no loss) or lossyear > (year - 2000)
    // For example, for 2013, lossyear > 13 (loss after 2013) means forest still present in 2013.
    // For 2018, lossyear > 18 (loss after 2018) means forest still present in 2018.
    const noLossUpToYear = lossYearBand.eq(0).or(lossYearBand.gt(year - 2000));

    // Mask for tree cover percentage in 2000
    const initialTreeCover = treeCover2000.gt(treeCoverThreshold);

    // Combine masks: initial tree cover AND no loss up to the target year
    return initialTreeCover.and(noLossUpToYear).selfMask().rename('forest');
  };

  const forest2013 = getForestCover(2013);
  const forest2018 = getForestCover(2018);

  const scale = 30; // Hansen data resolution is ~30m, use this scale for calculations.

  // 3. Calculation of forest area for 2013
  const pixelCount2013 = forest2013.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: geom,
    scale: scale,
    maxPixels: 1e10
  }).get('forest');

  let count2013 = await pixelCount2013.getInfo();

  if (count2013 === null || count2013 === 0) {
    console.log(`2013 Forest Pixels: ${count2013}`);
    console.log("C2"); // No valid pixels for 2013 after processing.
    return;
  }

  const area2013 = forest2013.multiply(ee.Image.pixelArea()).reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: geom,
    scale: scale,
    maxPixels: 1e10
  }).get('forest');

  // 4. Calculation of forest area for 2018
  const pixelCount2018 = forest2018.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: geom,
    scale: scale,
    maxPixels: 1e10
  }).get('forest');

  let count2018 = await pixelCount2018.getInfo();

  if (count2018 === null || count2018 === 0) {
    console.log(`2018 Forest Pixels: ${count2018}`);
    console.log("C2"); // No valid pixels for 2018 after processing.
    return;
  }

  const area2018 = forest2018.multiply(ee.Image.pixelArea()).reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: geom,
    scale: scale,
    maxPixels: 1e10
  }).get('forest');

  let finalArea2013 = await area2013.getInfo();
  let finalArea2018 = await area2018.getInfo();

  // 5. Validation & Final Answer
  if (finalArea2013 === null || isNaN(finalArea2013) || finalArea2018 === null || isNaN(finalArea2018)) {
    console.log("Calculation failed for forest area.");
    console.log("C3");
    return;
  }

  // Convert area from square meters to square kilometers for readability
  finalArea2013 /= 1e6;
  finalArea2018 /= 1e6;

  console.log(`Forest Area 2013 (sq km): ${finalArea2013.toFixed(2)} (Pixels: ${count2013})`);
  console.log(`Forest Area 2018 (sq km): ${finalArea2018.toFixed(2)} (Pixels: ${count2018})`);

  if (finalArea2018 < finalArea2013) {
    console.log("A"); // Yes, forest cover decreased.
  } else {
    console.log("B"); // No, forest cover did not decrease or increased/stayed same.
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
